DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT122-S1-Q3$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT122-S1-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT122-S1-Q3$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$(Yvette, implied) Banning sales to tourists would kill the art form.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$Without tourist buyers, young artists would stop making thangkas, and an art form without dedicated young artists decays and dies.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$Xavier's goal is to save a dying art form. Yvette shows that his plan would finish it off: no buyers, no young artists, no art. The plan causes the very thing it was meant to prevent.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Showing Xavier's plan would bring about the result it is meant to prevent.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT122-S1-Q3$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
